    inet_pton(AF_INET, "255.255.255.0", &addr->sin_addr);

    // Gateway
    addr = (struct sockaddr_in *)&route.rt_gateway;
    addr->sin_family = AF_INET;
    inet_pton(AF_INET, "192.168.1.1", &addr->sin_addr);

